import{_ as a,C as s,o as t,c as n,a1 as d,b as i,w as o,a as c,E as l,a0 as h}from"./chunks/framework.DYnGRJP5.js";const S=JSON.parse('{"title":"Database Schema (Firestore)","description":"","frontmatter":{},"headers":[],"relativePath":"2ndbrain/architecture/database-schema.md","filePath":"2ndbrain/architecture/database-schema.md"}'),u={name:"2ndbrain/architecture/database-schema.md"};function g(b,e,f,m,A,p){const r=s("Mermaid");return t(),n("div",null,[e[1]||(e[1]=d('<h1 id="database-schema-firestore" tabindex="-1">Database Schema (Firestore) <a class="header-anchor" href="#database-schema-firestore" aria-label="Permalink to &quot;Database Schema (Firestore)&quot;">​</a></h1><p>The 2ndBrain backend is powered by <strong>Firebase Firestore</strong>. The architecture relies on three primary collections.</p><p>Everything is scoped by the user&#39;s Google Auth <code>uid</code>. When data is fetched using <code>onSnapshot</code>, it always filters by <code>where(&#39;userId&#39;, &#39;==&#39;, user.uid)</code> to guarantee that no user ever receives another user&#39;s data.</p>',3)),(t(),i(h,null,{default:o(()=>[l(r,{id:"mermaid-9",class:"mermaid",graph:"erDiagram%0A%20%20%20%20USERS%20%7C%7C--o%7B%20NODES%20%3A%20%22owns%22%0A%20%20%20%20USERS%20%7C%7C--o%7B%20FOLDERS%20%3A%20%22owns%22%0A%20%20%20%20USERS%20%7C%7C--o%7B%20LINKS%20%3A%20%22owns%22%0A%20%20%20%20%0A%20%20%20%20FOLDERS%20%7C%7C--o%7B%20NODES%20%3A%20%22contains%22%0A%20%20%20%20NODES%20%7C%7C--o%7B%20LINKS%20%3A%20%22source%2Ftarget%22%0A%0A%20%20%20%20NODES%20%7B%0A%20%20%20%20%20%20%20%20string%20id%20PK%0A%20%20%20%20%20%20%20%20string%20name%20%0A%20%20%20%20%20%20%20%20string%20content%20%22JSON%20Stringified%20BlockNote%22%0A%20%20%20%20%20%20%20%20number%20val%20%22Node%20weight%22%0A%20%20%20%20%20%20%20%20string%20folder%20FK%20%22Folder%20ID%20or%20null%22%0A%20%20%20%20%20%20%20%20string%20userId%20FK%0A%20%20%20%20%7D%0A%0A%20%20%20%20LINKS%20%7B%0A%20%20%20%20%20%20%20%20string%20id%20PK%0A%20%20%20%20%20%20%20%20string%20source%20FK%20%22Source%20Node%20ID%22%0A%20%20%20%20%20%20%20%20string%20target%20FK%20%22Target%20Node%20ID%22%0A%20%20%20%20%20%20%20%20string%20userId%20FK%0A%20%20%20%20%7D%0A%0A%20%20%20%20FOLDERS%20%7B%0A%20%20%20%20%20%20%20%20string%20id%20PK%0A%20%20%20%20%20%20%20%20string%20name%0A%20%20%20%20%20%20%20%20string%20userId%20FK%0A%20%20%20%20%7D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=d('<h2 id="_1-nodes-collection-nodes" tabindex="-1">1. Nodes Collection (<code>/nodes</code>) <a class="header-anchor" href="#_1-nodes-collection-nodes" aria-label="Permalink to &quot;1. Nodes Collection (`/nodes`)&quot;">​</a></h2><p>This collection stores the actual notes/documents.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>The title of the node (used for linking and NLP matching)</td></tr><tr><td><code>content</code></td><td>string</td><td>A JSON-stringified representation of the BlockNote document</td></tr><tr><td><code>val</code></td><td>number</td><td>The weight/size of the node in the graph (default: 3)</td></tr><tr><td><code>folder</code></td><td>string | null</td><td>The ID of the folder it belongs to. If null, it&#39;s &quot;Unassigned&quot;.</td></tr><tr><td><code>createdAt</code></td><td>number</td><td><code>Date.now()</code> timestamp</td></tr><tr><td><code>userId</code></td><td>string</td><td>The Firebase Auth UID of the owner</td></tr></tbody></table><h2 id="_2-links-collection-links" tabindex="-1">2. Links Collection (<code>/links</code>) <a class="header-anchor" href="#_2-links-collection-links" aria-label="Permalink to &quot;2. Links Collection (`/links`)&quot;">​</a></h2><p>This collection defines the edges in the knowledge graph.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>source</code></td><td>string</td><td>The ID of the source node</td></tr><tr><td><code>target</code></td><td>string</td><td>The ID of the target node</td></tr><tr><td><code>userId</code></td><td>string</td><td>The Firebase Auth UID of the owner</td></tr></tbody></table><h2 id="_3-folders-collection-folders" tabindex="-1">3. Folders Collection (<code>/folders</code>) <a class="header-anchor" href="#_3-folders-collection-folders" aria-label="Permalink to &quot;3. Folders Collection (`/folders`)&quot;">​</a></h2><p>Stores the custom directories created by the user in the sidebar.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>string</td><td>The display name of the directory</td></tr><tr><td><code>createdAt</code></td><td>number</td><td><code>Date.now()</code> timestamp</td></tr><tr><td><code>userId</code></td><td>string</td><td>The Firebase Auth UID of the owner</td></tr></tbody></table><h2 id="safe-deletion-logic" tabindex="-1">Safe Deletion Logic <a class="header-anchor" href="#safe-deletion-logic" aria-label="Permalink to &quot;Safe Deletion Logic&quot;">​</a></h2><p>When a user deletes a folder, a batch <code>updateDoc</code> operation is triggered. It finds every node where <code>folder == deletedFolderId</code> and sets <code>folder: null</code>. This ensures that deleting a directory <strong>never</strong> deletes the user&#39;s actual notes; they just safely fall back to the root &quot;Unassigned&quot; pool.</p>',11))])}const D=a(u,[["render",g]]);export{S as __pageData,D as default};
